"use client";

import { useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import {
	Tooltip,
	TooltipContent,
	TooltipProvider,
	TooltipTrigger,
} from "@/components/ui/tooltip";
import {
	RiCodeFill,
	RiFacebookFill,
	RiMailLine,
	RiTwitterXFill,
} from "@remixicon/react";
import { CheckIcon, CopyIcon } from "lucide-react";

import { cn } from "@/lib/utils";

export default function Component() {
	const id = useId();
	const [copied, setCopied] = useState<boolean>(false);
	const inputRef = useRef<HTMLInputElement>(null);

	const handleCopy = () => {
		if (inputRef.current) {
			navigator.clipboard.writeText(inputRef.current.value);
			setCopied(true);
			setTimeout(() => setCopied(false), 1500);
		}
	};

	return (
		<div className="flex flex-col gap-4">
			<Popover>
				<PopoverTrigger asChild>
					<Button variant="outline">Share</Button>
				</PopoverTrigger>
				<PopoverContent className="w-72">
					<div className="flex flex-col gap-3 text-center">
						<div className="text-sm font-medium">Share code</div>
						<div className="flex flex-wrap justify-center gap-2">
							<Button size="icon" variant="outline" aria-label="Embed">
								<RiCodeFill size={16} aria-hidden="true" />
							</Button>
							<Button
								size="icon"
								variant="outline"
								aria-label="Share on Twitter"
							>
								<RiTwitterXFill size={16} aria-hidden="true" />
							</Button>
							<Button
								size="icon"
								variant="outline"
								aria-label="Share on Facebook"
							>
								<RiFacebookFill size={16} aria-hidden="true" />
							</Button>
							<Button
								size="icon"
								variant="outline"
								aria-label="Share via email"
							>
								<RiMailLine size={16} aria-hidden="true" />
							</Button>
						</div>
						<div className="space-y-2">
							<div className="relative">
								<Input
									ref={inputRef}
									id={id}
									className="pe-9"
									type="text"
									defaultValue="https://originui.com/Avx8HD"
									aria-label="Share link"
									readOnly
								/>
								<TooltipProvider delayDuration={0}>
									<Tooltip>
										<TooltipTrigger asChild>
											<button
												onClick={handleCopy}
												className="text-muted-foreground/80 hover:text-foreground focus-visible:border-ring focus-visible:ring-ring/50 absolute inset-y-0 inset-e-0 flex h-full w-9 items-center justify-center rounded-e-md transition-[color,box-shadow] outline-hidden focus:z-10 focus-visible:ring-[3px] disabled:pointer-events-none disabled:cursor-not-allowed"
												aria-label={
													copied ? "Copied" : "Copy to clipboard"
												}
												disabled={copied}
											>
												<div
													className={cn(
														"transition-all",
														copied
															? "scale-100 opacity-100"
															: "scale-0 opacity-0"
													)}
												>
													<CheckIcon
														className="stroke-emerald-500"
														size={16}
														aria-hidden="true"
													/>
												</div>
												<div
													className={cn(
														"absolute transition-all",
														copied
															? "scale-0 opacity-0"
															: "scale-100 opacity-100"
													)}
												>
													<CopyIcon size={16} aria-hidden="true" />
												</div>
											</button>
										</TooltipTrigger>
										<TooltipContent className="px-2 py-1 text-xs">
											Copy to clipboard
										</TooltipContent>
									</Tooltip>
								</TooltipProvider>
							</div>
						</div>
					</div>
				</PopoverContent>
			</Popover>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

